/* ---------- v3: case law (midterm site + the six judgments of the case-law list it did not cover) ---------- */
const CH2T={c1:'t1',c2:'t1',c3:'t2',c4:'t3',c5:'t3',c6:'t4',c7:'t4'};
const CASELAW=MIDCASES.map(c=>Object.assign({},c,{topic:CH2T[c.ch],theme:c.topic,src:'Midterm site',ch:undefined})).concat([
 {id:'ardagh',name:'Ardagh Metal Beverage Holdings v EUIPO',court:'General Court (TEU)',date:'7 July 2021',no:'T-668/19',topic:'t4',theme:'Sound mark, distinctiveness',src:'Case-law list (Session 4)',
  facts:'Ardagh applied for an EU sound mark: the sound of a drinks can being opened, followed by a silence and a fizzing sound, for beverages and their containers. EUIPO refused it.',
  question:'Is the sound of opening a can distinctive for drinks and cans?',
  holding:'No. The sound is perceived as a functional, technical element inherent in the use of the goods (and as a quality of the drink), not as an indication of commercial origin. The silence and the fizzing do not add enough resonance.',
  why:'A sound mark must be perceived as an origin, not as the normal noise of the product. Same logic as for shapes: a functional characteristic is not distinctive.',
  flag:'The common slides only give the lesson; the details of the facts are a summary by the site.'},
 {id:'sabel',name:'Sabel v Puma',court:'CJEU',date:'11 November 1997',no:'C-251/95',topic:'t5',theme:'Likelihood of confusion: global assessment',src:'Case-law list (Session 5)',
  facts:'Sabel applied in Germany for a figurative mark showing a bounding cheetah with the word “SABEL” for leather goods and clothing. Puma, owner of earlier marks showing a bounding puma, opposed.',
  question:'Is a mere association between two marks, through their similar meaning (a bounding feline), enough for a likelihood of confusion?',
  holding:'No. Mere association is not in itself sufficient. The likelihood of confusion must be appreciated globally, taking into account all relevant factors; the global appreciation of the visual, aural and conceptual similarity rests on the overall impression of the marks, bearing in mind their distinctive and dominant components. The average consumer perceives a mark as a whole.',
  why:'Source of the global assessment and of the three comparisons (visual, aural, conceptual) used in Session 5.',
  flag:'Facts: summary by the site (outside the slides); the slides cite the case for the global assessment and the three similarity factors.'},
 {id:'canon',name:'Canon Kabushiki Kaisha v Metro-Goldwyn-Mayer',court:'CJEU',date:'29 September 1998',no:'C-39/97',topic:'t5',theme:'Likelihood of confusion: definition, interdependence',src:'Case-law list (Session 5)',
  facts:'MGM applied in Germany for “CANNON” for films and video recordings. Canon opposed on the basis of its earlier mark “CANON” for cameras, video recorders and television sets.',
  question:'When comparing the goods, can the distinctiveness (reputation) of the earlier mark be taken into account? What is a likelihood of confusion?',
  holding:'Yes. The factors are interdependent: a lesser degree of similarity between the goods may be offset by a greater degree of similarity between the marks, and vice versa; marks with a highly distinctive character enjoy broader protection. Likelihood of confusion = the risk that the public might believe that the goods come from the same undertaking or from economically-linked undertakings.',
  why:'The definition quoted in the slides, and the interdependence of the factors (why the assessment is “global”).',
  flag:'Facts: summary by the site (outside the slides).'},
 {id:'lloyd',name:'Lloyd Schuhfabrik Meyer v Klijsen Handel',court:'CJEU',date:'22 June 1999',no:'C-342/97',topic:'t5',theme:'Relevant public, distinctiveness of the earlier mark',src:'Case-law list (Session 5)',
  facts:'Lloyd, owner of the mark “LLOYD” for shoes, sued Klijsen, which sold shoes under “LOINT’S”.',
  question:'Can aural similarity alone create a likelihood of confusion? How is the average consumer defined, and how is the distinctiveness of the earlier mark assessed?',
  holding:'Aural similarity alone can be enough. The average consumer is reasonably well-informed and reasonably observant and circumspect; he rarely compares the marks directly and relies on the imperfect picture he has kept in mind; his attention varies with the category of goods. Distinctiveness: inherent characteristics (descriptive elements), market share, intensity, geographical extent and duration of use, investment in promotion, proportion of the public who identifies the goods (no fixed percentage).',
  why:'Gives the “relevant public” and the factors of the distinctiveness of the earlier mark used in Session 5 (and for reputation).',
  flag:'Facts: summary by the site (outside the slides).'},
 {id:'grundig',name:'Consten and Grundig v Commission',court:'CJEU (CJCE)',date:'13 July 1966',no:'Joined cases 56/64 and 58/64',topic:'t7',theme:'Trademark rights and the single market',src:'Case-law list (Session 8)',
  facts:'Grundig made Consten its exclusive distributor in France and let it register the mark “GINT” there, so that Consten could block parallel imports of Grundig products bought in other Member States.',
  question:'Can a national trademark right be used to partition the common market?',
  holding:'No. The agreement and the use of the GINT mark to stop parallel imports breach EU competition law (now Art. 101 TFEU). The existence of the trademark right is not affected, but its exercise is limited when it serves to isolate national markets.',
  why:'Starting point of the rule that trademark rights cannot be used to split the single market; leads to exhaustion (Centrafarm).',
  flag:'Not developed in the common slides: summary by the site (outside the slides). The list writes “CJEU, 13 July 1966, Grundig-Verkaufs-GmbH, C-56/64 and 58/64”.'},
 {id:'centrafarm',name:'Centrafarm v Winthrop',court:'CJEU (CJCE)',date:'31 October 1974',no:'C-16/74',topic:'t7',theme:'Exhaustion of rights',src:'Case-law list (Session 8)',
  facts:'Winthrop held the mark “Negram” for a medicine in the Netherlands. Centrafarm bought Negram put on the UK market by the same group, where it was cheaper, and imported it into the Netherlands. Winthrop sued for infringement.',
  question:'Can a trademark owner rely on his national right to stop the import of goods put on the market in another Member State by himself or with his consent?',
  holding:'No. The specific subject matter of a trademark is the exclusive right to use it to put the goods into circulation for the first time, and to protect it against competitors who would sell goods illegally bearing it. Once the goods are marketed in a Member State by the owner or with his consent, the right is exhausted.',
  why:'Origin of the exhaustion of rights (Session 8 exception): resale of genuine goods first sold in the EEA with consent cannot be stopped, unless legitimate reasons (alteration).',
  flag:'Not developed in the common slides: summary by the site (outside the slides). The list spells it “Centrapharm”.'}]);

